#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

void printInt128(i128 value) {
    if (value == 0) {
        cout << 0;
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, k, M;
    cin >> n >> k >> M;

    vector<int64> costs(k);
    for (auto& cost : costs) cin >> cost;
    sort(costs.begin(), costs.end());

    vector<i128> prefix(k + 1, 0);
    for (int64 i = 0; i < k; ++i)
        prefix[i + 1] = prefix[i] + costs[i];

    i128 answer = 0;
    const i128 budget = M;
    const i128 limit = n;

    for (int64 p = 0; p < k; ++p) {
        i128 fixedCost = limit * prefix[p];
        if (fixedCost > budget) break;

        i128 remainingBudget = budget - fixedCost;
        i128 remainingCost = prefix[k] - prefix[p];
        i128 unitCost = costs[p];
        i128 packageValue = k - p + 1;
        i128 fixedValue = limit * p;
        i128 variableValue = 0;

        if (packageValue * unitCost >= remainingCost) {
            i128 packages = min(limit, remainingBudget / remainingCost);
            i128 rest = remainingBudget - packages * remainingCost;
            i128 units = min(limit - packages, rest / unitCost);
            variableValue = packageValue * packages + units;
        } else {
            i128 allUnitsCost = unitCost * limit;

            if (remainingBudget < allUnitsCost) {
                variableValue = remainingBudget / unitCost;
            } else {
                i128 extraBudget = remainingBudget - allUnitsCost;
                i128 replacementCost = remainingCost - unitCost;
                i128 packages = min(limit, extraBudget / replacementCost);
                variableValue = limit + (packageValue - 1) * packages;
            }
        }

        answer = max(answer, fixedValue + variableValue);
    }

    printInt128(answer);
    return 0;
}

