int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 nInput, kInput, mInput;
    cin >> nInput >> kInput >> mInput;

    int k = static_cast<int>(kInput);
    vector<int64> cost(k);
    for (auto &x : cost) cin >> x;
    sort(cost.begin(), cost.end());

    i128 n = nInput;
    i128 M = mInput;

    vector<i128> pref(k + 1, 0);
    for (int i = 0; i < k; ++i)
        pref[i + 1] = pref[i] + cost[i];

    i128 totalCost = pref[k];
    i128 maxMinimum = (totalCost == 0 ? n : min(n, M / totalCost));

    vector<i128> candidates = {0, maxMinimum};

    auto addCandidate = [&](i128 t) {
        if (t < 0) t = 0;
        if (t > maxMinimum) t = maxMinimum;
        candidates.push_back(t);
    };

    for (int q = 0; q < k; ++q) {
        i128 denominator = totalCost - pref[q];
        i128 numerator = M - n * pref[q];

        if (denominator > 0 && numerator >= 0) {
            i128 boundary = numerator / denominator;
            addCandidate(boundary);
            addCandidate(boundary + 1);
        }
    }

    auto evaluate = [&](i128 minimumCount) -> i128 {
        i128 remainingTime = M - minimumCount * totalCost;
        i128 capacity = n - minimumCount;

        int low = 0, high = k;
        while (low < high) {
            int mid = (low + high + 1) / 2;
            if (capacity * pref[mid] <= remainingTime)
                low = mid;
            else
                high = mid - 1;
        }

        int fullTypes = low;
        i128 extra = capacity * fullTypes;
        remainingTime -= capacity * pref[fullTypes];

        if (fullTypes < k) {
            extra += min(capacity, remainingTime / cost[fullTypes]);
        }

        return minimumCount * (k + 1LL) + extra;
    };

    i128 answer = 0;
    for (i128 t : candidates)
        answer = max(answer, evaluate(t));

    printInt128(answer);
    return 0;
}

