    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 nInput, kInput, mInput;
    cin >> nInput >> kInput >> mInput;

    int k = static_cast<int>(kInput);
    vector<int64> cost(k);
    for (auto& x : cost) cin >> x;

    sort(cost.begin(), cost.end());

    i128 n = nInput;
    i128 M = mInput;

    vector<i128> prefix(k + 1, 0);
    for (int i = 0; i < k; ++i) {
        prefix[i + 1] = prefix[i] + cost[i];
    }

    i128 totalCost = prefix[k];

    if (M >= n * totalCost) {
        print128((i128)(k + 1) * n);
        return 0;
    }

    i128 maxMinimum = min(n, M / totalCost);
    i128 answer = 0;

    for (int p = 0; p < k; ++p) {
        i128 currentPrefix = prefix[p];
        i128 nextPrefix = prefix[p + 1];

        i128 upperNumerator = M - n * currentPrefix;
        i128 upperDenominator = totalCost - currentPrefix;

        if (upperNumerator < 0) continue;

        i128 low = 0;
        i128 high = upperNumerator / upperDenominator;

        i128 lowerNumerator = M - n * nextPrefix;
        i128 lowerDenominator = totalCost - nextPrefix;

        if (lowerDenominator == 0) {
            if (lowerNumerator >= 0) continue;
        } else if (lowerNumerator >= 0) {
            low = lowerNumerator / lowerDenominator + 1;
        }

        low = max<i128>(low, 0);
        high = min(high, maxMinimum);

        if (low > high) continue;

        auto evaluate = [&](i128 t) {
            i128 capacity = n - t;
            i128 remaining = M - t * totalCost;
            i128 afterFull = remaining - capacity * currentPrefix;
            i128 partial = afterFull / cost[p];
            partial = min(partial, capacity);

            i128 extras = (i128)p * capacity + partial;
            i128 value = (i128)(k + 1) * t + extras;
            answer = max(answer, value);
        };

        evaluate(low);
        if (high != low) evaluate(high);
    }

    print128(answer);
    return 0;
}

