    cin.tie(nullptr);

    int64 n, k, M;
    cin >> n >> k >> M;

    vector<int64> cost(k);
    for (auto &x : cost) cin >> x;
    sort(cost.begin(), cost.end());

    vector<i128> prefix(k + 1, 0);
    for (int64 i = 0; i < k; ++i)
        prefix[i + 1] = prefix[i] + cost[i];

    i128 totalCost = prefix[k];

    if ((i128)M >= (i128)n * totalCost) {
        printInt128((i128)(k + 1) * n);
        return 0;
    }

    i128 maxBase = min<i128>(n, (i128)M / totalCost);
    i128 answer = 0;

    auto evaluate = [&](i128 base) {
        if (base < 0 || base > maxBase) return;

        i128 capacity = (i128)M - base * totalCost;
        i128 limit = (i128)n - base;

        int64 lo = 0, hi = k;
        while (lo < hi) {
            int64 mid = lo + (hi - lo + 1) / 2;
