        i128 denominator = totalCost - prefix[j];
        i128 numerator = (i128)M - (i128)n * prefix[j];

        if (denominator > 0 && numerator >= 0) {
            i128 boundary = numerator / denominator;
            evaluate(boundary);
            evaluate(boundary + 1);
        }
    }

    printInt128(answer);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

i128 floor_div(i128 a, i128 b) {
    if (a >= 0) return a / b;
    return -((-a + b - 1) / b);
}

i128 ceil_div(i128 a, i128 b) {
    if (a >= 0) return (a + b - 1) / b;
    return -((-a) / b);
}

void print_i128(i128 x) {
    if (x == 0) {
        cout << 0;
        return;
    }
    if (x < 0) {
        cout << '-';
        x = -x;
    }
    string s;
    while (x > 0) {
        s.push_back(char('0' + x % 10));
        x /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, k, M;
    cin >> n >> k >> M;

    vector<int64> cost(k);
    for (auto &x : cost) cin >> x;
    sort(cost.begin(), cost.end());

    vector<i128> prefix(k + 1, 0);
    for (int64 i = 0; i < k; ++i)
        prefix[i + 1] = prefix[i] + cost[i];

    const i128 N = n;
    const i128 K = k;
    const i128 budget = M;
    const i128 totalCost = prefix[k];

    auto feasible = [&](i128 target) {
        i128 baseline = ceil_div(target, K + 1);
        if (baseline <= N && baseline * totalCost <= budget)
            return true;

        for (int64 p = 0; p < k; ++p) {
            i128 P = p;

            i128 left = ceil_div(
                target - (P + 1) * N,
                K - P
            );
            i128 right = floor_div(
                target - P * N,
                K + 1 - P
            );

            left = max<i128>(left, 0);
            right = min<i128>(right, N);
            if (left > right) continue;

            auto check = [&](i128 t) {
                i128 capacity = N - t;
                i128 remaining =
                    target - (K + 1) * t - P * capacity;

                i128 requiredCost =
                    t * totalCost +
                    capacity * prefix[p] +
                    remaining * (i128)cost[p];

                return requiredCost <= budget;
            };

            if (check(left) || check(right))
                return true;
        }
        return false;
    };

    i128 low = 0;
    i128 high = (K + 1) * N;

    while (low < high) {
        i128 mid = low + (high - low + 1) / 2;
        if (feasible(mid))
            low = mid;
        else
            high = mid - 1;
    }

    print_i128(low);
    return 0;
}

